import React from 'react';

const testimonials = [
  { name: 'DJ Malik', time: "Il y'a deux heures", text: "Grâce à Djamano, j'ai trouvé de nouveaux clients sans bouger de mon studio.", featured: false },
  { name: 'Clarisse Kaboré', time: "Il y'a 2 semaines", text: "J'adore pouvoir découvrir des événements près de moi et acheter mes billets directement en ligne.", featured: true },
  { name: 'Shailesh Kushwaha', time: "Il y'a un mois", text: "Avant Djamano, gérer la billetterie et les réservations était un vrai casse-tête. Aujourd'hui, tout est centralisé.", featured: false },
];

const ClockIcon = ({ color = '#888' }) => (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="9" />
    <path d="M12 7v5l3 2" />
  </svg>
);

const TestimonialsSection = () => {
  const s = {
    section: { background: '#F7F7F7', padding: '90px 32px', fontFamily: 'Poppins, sans-serif' },
    wrapper: { maxWidth: 1200, margin: '0 auto' },
    eyebrow: { display: 'inline-flex', alignItems: 'center', gap: 8, background: '#FFF3ED', color: '#FF5A00', padding: '6px 14px', borderRadius: 30, fontSize: 12, fontWeight: 600, marginBottom: 20 },
    title: { fontSize: 34, fontWeight: 800, color: '#111', fontFamily: 'Poppins, sans-serif', letterSpacing: '-0.6px', marginBottom: 48 },
    orange: { color: '#FF5A00' },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 22 },
    card: (f) => ({
      borderRadius: 26,
      padding: '28px 24px',
      display: 'flex',
      flexDirection: 'column',
      gap: 16,
      background: f ? 'linear-gradient(135deg, #ff984c 0%, #ff5a00 100%)' : '#F7F7F7',
      border: 'none',
      boxShadow: f ? '0 18px 50px rgba(255, 90, 0, 0.18)' : 'none',
    }),
    cardTop: { display: 'flex', flexDirection: 'column', gap: 8 },
    timeRow: { display: 'inline-flex', alignItems: 'center', gap: 8 },
    time: (f) => ({ fontSize: 12, fontFamily: 'Poppins, sans-serif', fontWeight: 400, color: f ? 'rgba(255,255,255,.85)' : '#888' }),
    name: (f) => ({ fontSize: 16, fontWeight: 700, fontFamily: 'Poppins, sans-serif', color: f ? '#fff' : '#111' }),
    text: (f) => ({ fontSize: 13.5, lineHeight: 1.72, fontFamily: 'Poppins, sans-serif', fontWeight: 400, color: f ? 'rgba(255,255,255,.88)' : '#666' }),
    stars: { display: 'flex', gap: 6 },
    star: (f) => ({ fontSize: 20, lineHeight: 1, color: f ? '#fff' : '#999' }),
  };

  return (
    <section style={s.section}>
      <div style={s.wrapper}>

        <h2 style={s.title}>Témoignages d'<span style={s.orange}>Utilisateurs </span>satisfaits</h2>
        <div style={s.grid}>
          {testimonials.map((t) => (
            <div key={t.name} style={s.card(t.featured)}>
              <div style={s.cardTop}>
                <div style={s.name(t.featured)}>{t.name}</div>
                <div style={s.timeRow}>
                  <ClockIcon color={t.featured ? 'rgba(255,255,255,.85)' : '#888'} />
                  <span style={s.time(t.featured)}>{t.time}</span>
                </div>
              </div>
              <div style={s.text(t.featured)}>{t.text}</div>
              <div style={s.stars}>
                {[...Array(5)].map((_, i) => <span key={i} style={s.star(t.featured)}>★</span>)}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default TestimonialsSection;
